FILES['tests_b1.py'] = r'''"""Tests for plan/block1/ask.py (run by harness.py). The client is a stand-in shaped like OpenAI(): no model is called."""
from fakes import FakeOpenAI

FILE = "ask.py"
QUESTION = "What color is the Zorblat beacon?"
DOCUMENT = "Field manual, page 9. The Zorblat beacon is painted teal so that crews can find it at dusk."


def need(m, name):
    assert hasattr(m, name), f"{FILE} has nothing named {name}"
    return getattr(m, name)


def messages_of(m):
    msgs = need(m, "build_messages")(QUESTION, DOCUMENT)
    assert isinstance(msgs, list), f"build_messages returned {type(msgs).__name__}, expected a list"
    return msgs


def test_two_messages(m):
    """build_messages returns a system message, then a user message"""
    msgs = messages_of(m)
    assert len(msgs) == 2, f"it returned {len(msgs)} messages, expected 2"
    assert all(isinstance(x, dict) for x in msgs), "each message must be a dictionary"
    roles = [x.get("role") for x in msgs]
    assert roles == ["system", "user"], f"roles were {roles!r}, expected ['system', 'user']"


def test_system_instructions(m):
    """The system message carries your instructions (20 characters or more)"""
    system = messages_of(m)[0].get("content")
    assert isinstance(system, str) and len(system.strip()) >= 20, "the system message is empty or too short to instruct the model"
    assert DOCUMENT not in system, "put the document in the user message, not the system message"


def test_user_has_document_and_question(m):
    """The user message contains the document and the question"""
    user = messages_of(m)[1].get("content")
    assert isinstance(user, str), "the user message content must be a string"
    assert DOCUMENT in user, "the document text is not in the user message"
    assert QUESTION in user, "the question is not in the user message"


def test_ask_one_request(m):
    """ask sends build_messages(question, document) in one Chat Completions call"""
    client = FakeOpenAI(["Teal."])
    need(m, "ask")(client, QUESTION, DOCUMENT)
    reqs = client.requests("chat.completions.create")
    assert len(reqs) == 1, f"{len(reqs)} requests were made; expected one"
    assert reqs[0]["messages"] == need(m, "build_messages")(QUESTION, DOCUMENT), \
        "the request's messages are not build_messages(question, document)"


def test_ask_model(m):
    """ask uses gpt-4.1-mini unless it is given another model"""
    client = FakeOpenAI(["a", "b"])
    need(m, "ask")(client, QUESTION, DOCUMENT)
    need(m, "ask")(client, QUESTION, DOCUMENT, model="gpt-5-nano")
    got = [r["model"] for r in client.requests()]
    assert got == ["gpt-4.1-mini", "gpt-5-nano"], f"the models sent were {got}; expected ['gpt-4.1-mini', 'gpt-5-nano']"


def test_ask_reply(m):
    """ask returns the reply's text, without whitespace around it"""
    got = need(m, "ask")(FakeOpenAI(["  Teal.\n\n"]), QUESTION, DOCUMENT)
    assert got == "Teal.", f"a reply of '  Teal.\\n\\n' came back as {got!r}; expected 'Teal.'"
'''
FILES['tests_b2.py'] = r'''"""Tests for plan/block2/chat.py (run by harness.py). The client is a stand-in shaped like OpenAI(): no model is called."""
import json
import os
import tempfile

from fakes import FakeOpenAI, ToolCalls, check_tools

FILE = "chat.py"
FINAL = json.dumps({"answer": "Teal.", "source": "beacon.md"})


def need(m, name):
    assert hasattr(m, name), f"{FILE} has nothing named {name}"
    return getattr(m, name)


def start():
    return [{"role": "system", "content": "Answer from the documents."}, {"role": "user", "content": "What color is the beacon?"}]


def plain(message):
    """A message as a dict, whether it was kept as a dict or as the SDK's message object."""
    if isinstance(message, dict):
        return message
    return message.model_dump(exclude_none=True) if hasattr(message, "model_dump") else vars(message)


def test_answer_model(m):
    """Answer accepts {"answer": ..., "source": ...} and rejects an empty answer or a missing source"""
    import pydantic
    cls = need(m, "Answer")
    assert isinstance(cls, type) and issubclass(cls, pydantic.BaseModel), "Answer must be a pydantic BaseModel"
    a = cls.model_validate({"answer": "Teal.", "source": "beacon.md"})
    assert (a.answer, a.source) == ("Teal.", "beacon.md"), "the fields did not come back as given"
    for bad in ({"answer": "", "source": "beacon.md"}, {"answer": "Teal."}):
        try:
            cls.model_validate(bad)
        except pydantic.ValidationError:
            continue
        raise AssertionError(f"Answer accepted {bad!r}")


def test_list_documents(m):
    """list_documents returns the sorted names of the .md and .txt files in a folder"""
    fn = need(m, "list_documents")
    with tempfile.TemporaryDirectory() as d:
        for name in ("b.md", "a.txt", "c.pdf"):
            open(os.path.join(d, name), "w").close()
        os.mkdir(os.path.join(d, "sub"))
        open(os.path.join(d, "sub", "x.md"), "w").close()
        got = fn(d)
    assert got == ["a.txt", "b.md"], f"for a folder holding a.txt, b.md, c.pdf and sub/x.md it gave {got!r}, expected ['a.txt', 'b.md']"


def test_tools(m):
    """TOOLS describes list_documents to the model, with a required folder parameter"""
    tools = need(m, "TOOLS")
    check_tools(tools)
    fn = [t["function"] for t in tools if t["function"].get("name") == "list_documents"]
    assert fn, "TOOLS has no entry named list_documents"
    params = fn[0].get("parameters") or {}
    assert "folder" in params.get("properties", {}), "the list_documents entry has no folder property"
    assert "folder" in params.get("required", []), "list the folder as required, so the model always gives one"
    assert len(fn[0].get("description", "")) >= 20, "describe the tool, so the model knows when to call it"


def test_direct_answer(m):
    """run_chat returns an Answer when the model replies with the final JSON straight away"""
    client, messages = FakeOpenAI([FINAL]), start()
    got = need(m, "run_chat")(client, messages, {})
    assert isinstance(got, need(m, "Answer")), f"run_chat returned {type(got).__name__}, expected an Answer"
    assert (got.answer, got.source) == ("Teal.", "beacon.md"), f"got {(got.answer, got.source)!r}"
    reqs = client.requests()
    assert len(reqs) == 1, f"{len(reqs)} requests were made; expected one"
    assert reqs[0].get("tools") == need(m, "TOOLS"), "send TOOLS with the request, so the model can call them"
    assert reqs[0]["model"] == "gpt-4.1-mini", f"the model was {reqs[0]['model']!r}; the default is gpt-4.1-mini"
    assert len(messages) == 3 and plain(messages[-1]).get("role") == "assistant", \
        "append the model's reply to the messages list you were given"


def test_tool_round(m):
    """run_chat runs a requested tool, sends back its result, then returns the final Answer"""
    seen = []

    def lister(folder):
        seen.append(folder)
        return ["beacon.md", "crew.md"]

    client, messages = FakeOpenAI([ToolCalls(("list_documents", {"folder": "plan/docs"})), FINAL]), start()
    got = need(m, "run_chat")(client, messages, {"list_documents": lister}, model="gpt-5-nano")
    assert seen == ["plan/docs"], f"the tool was called with {seen!r}, expected one call with folder='plan/docs'"
    assert (got.answer, got.source) == ("Teal.", "beacon.md"), f"got {(got.answer, got.source)!r}"
    roles = [plain(x).get("role") for x in messages]
    assert roles == ["system", "user", "assistant", "tool", "assistant"], f"message roles ended as {roles!r}"
    tool_msg = plain(messages[3])
    assert isinstance(tool_msg.get("content"), str), "the tool message content must be a string (use json.dumps on the result)"
    assert json.loads(tool_msg["content"]) == ["beacon.md", "crew.md"], "the tool message content is not the tool's result as JSON"
    assert [r["model"] for r in client.requests()] == ["gpt-5-nano"] * 2, "pass the model you are given to every call"


def test_two_tools_in_one_reply(m):
    """When one reply asks for two tools, run_chat answers both, in order"""
    log = []

    def lister(folder):
        log.append(folder)
        return [folder + "/a.md"]

    client, messages = FakeOpenAI([ToolCalls(("list_documents", {"folder": "x"}), ("list_documents", {"folder": "y"})), FINAL]), start()
    need(m, "run_chat")(client, messages, {"list_documents": lister})
    assert log == ["x", "y"], f"the tool calls ran as {log!r}, expected ['x', 'y']"
    asked = [c["id"] for c in plain(messages[2]).get("tool_calls", [])]
    answered = [plain(x).get("tool_call_id") for x in messages if plain(x).get("role") == "tool"]
    assert answered == asked, f"the tool messages answer ids {answered!r}; the calls were {asked!r}"


def test_gives_up(m):
    """run_chat raises RuntimeError rather than loop forever (5 model calls at most)"""
    client = FakeOpenAI([ToolCalls(("list_documents", {"folder": "x"})) for _ in range(9)])
    try:
        need(m, "run_chat")(client, start(), {"list_documents": lambda folder: []})
    except RuntimeError:
        n = len(client.requests())
        assert n <= 5, f"it called the model {n} times before stopping, expected at most 5"
        return
    raise AssertionError("a model that keeps asking for tools never made run_chat raise RuntimeError")


def test_bad_final_reply(m):
    """run_chat raises ValueError when the final reply is not the expected JSON"""
    for reply in ("The beacon is teal.", json.dumps({"answer": "Teal."})):
        try:
            need(m, "run_chat")(FakeOpenAI([reply]), start(), {})
        except ValueError:
            continue
        raise AssertionError(f"a final reply of {reply!r} did not raise ValueError")
'''
